package main

import (
	"fmt"
	"slices"
	"strings"
)

func main() {
	left := []string{"Go", "Ruby"}
	right := []string{"go", "ruby"}
	fmt.Println("exact:", slices.Equal(left, right))
	fmt.Println("folded:", slices.EqualFunc(left, right, strings.EqualFold))

	var nilNames []string
	emptyNames := []string{}
	fmt.Println("same contents:", slices.Equal(nilNames, emptyNames))
	fmt.Println("nil states:", nilNames == nil, emptyNames == nil)
}
