package main

import (
	"encoding/json"
	"fmt"
)

func mustJSON(value any) string {
	data, err := json.Marshal(value)
	if err != nil {
		panic(err)
	}
	return string(data)
}

func main() {
	var nilSlice []int
	emptySlice := []int{}
	fmt.Println("slices:", len(nilSlice), nilSlice == nil, len(emptySlice), emptySlice == nil)
	nilSlice = append(nilSlice, 1)
	fmt.Println("appended:", nilSlice)

	var nilMap map[string]int
	emptyMap := map[string]int{}
	fmt.Println("maps:", len(nilMap), nilMap == nil, len(emptyMap), emptyMap == nil)
	fmt.Println("read:", nilMap["x"])
	delete(nilMap, "x")
	emptyMap["x"] = 1
	fmt.Println("written:", emptyMap)

	fmt.Println("json:", mustJSON([]int(nil)), mustJSON([]int{}), mustJSON(map[string]int(nil)), mustJSON(map[string]int{}))
}
