package main

import (
	"fmt"
	"slices"
)

type Point struct {
	X int
	Y int
}

type Record struct {
	Name string
	Tags []string
}

func equalRecord(left, right Record) bool {
	return left.Name == right.Name && slices.Equal(left.Tags, right.Tags)
}

func main() {
	first := Point{X: 2, Y: 3}
	second := Point{X: 2, Y: 3}
	labels := map[Point]string{{X: 0, Y: 0}: "origin"}
	fmt.Println("point:", first == second, labels[Point{}])

	left := Record{Name: "guide", Tags: []string{"go", "types"}}
	right := Record{Name: "guide", Tags: []string{"go", "types"}}
	fmt.Println("record contents:", equalRecord(left, right))
}
